/* push-sw.js — push notification handling for the service worker.
 *
 * WHAT THIS FILE IS
 * The app's service worker is generated by vite-plugin-pwa (Workbox). It caches
 * the app shell so the app opens offline. This hand-written file is pulled into
 * that same worker with `importScripts` (see `workbox.importScripts` in
 * vite.config.ts), so there is still exactly ONE service worker. Nothing here
 * touches caching.
 *
 * A service worker runs in the background, separately from any open page, and
 * the browser can start it even when the app is closed. That is what makes
 * push possible: the push arrives, the browser wakes this code, and this code
 * shows the notification.
 *
 * Plain JavaScript on purpose: files in public/ are copied as-is, not compiled.
 *
 * Design: docs/NOTIFICATIONS_SPEC.md §2.3, §9.5.
 */

/* global self, clients */

// ---------------------------------------------------------------------------
// push — a message arrived from Firebase Cloud Messaging (FCM)
// ---------------------------------------------------------------------------
//
// The Cloud Function sends a DATA-only message. FCM wraps it as JSON:
//   { "data": { "title": "…", "body": "…", "url": "…", "kind": "…" },
//     "from": "<sender id>", "fcmMessageId": "…" }
//
// iOS REQUIRES a visible notification for every push, or it may revoke the
// subscription. So whatever the payload looks like — even unreadable — this
// handler always ends in showNotification().
self.addEventListener('push', (event) => {
  let payload = {}
  try {
    payload = event.data ? event.data.json() : {}
  } catch {
    payload = {}
  }
  const data = payload.data || {}
  // Fallback: a message sent with a `notification` block (e.g. a test message
  // from the Firebase console) carries its text there instead.
  const notification = payload.notification || {}

  const title = data.title || notification.title || 'GlobeExpenses'
  const options = {
    // Last-resort text (unreadable payload). The worker cannot see the app's
    // language store, so it follows the browser language.
    body:
      data.body ||
      notification.body ||
      (/^fr\b/i.test(self.navigator.language || '') ? 'Vous avez de nouvelles activités.' : 'You have new activity.'),
    icon: '/images/icon-192.png',
    // Read back in `notificationclick` below.
    data: { url: data.url || '/' },
  }

  // waitUntil keeps the worker alive until the notification is on screen.
  event.waitUntil(self.registration.showNotification(title, options))
})

// ---------------------------------------------------------------------------
// notificationclick — the user tapped a notification
// ---------------------------------------------------------------------------
//
// If the app is already open somewhere, bring that window forward and ask it
// to navigate in-app (no reload, state kept). Otherwise open a new window on
// the target page.
self.addEventListener('notificationclick', (event) => {
  event.notification.close()

  // Only ever open pages of this app: resolve against our own origin and
  // discard anything that ends up elsewhere.
  const raw = (event.notification.data && event.notification.data.url) || '/'
  let target = new URL('/', self.location.origin)
  try {
    const parsed = new URL(raw, self.location.origin)
    if (parsed.origin === self.location.origin) target = parsed
  } catch {
    // keep the default
  }
  const path = target.pathname + target.search

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(async (windows) => {
      const open = windows.find((w) => new URL(w.url).origin === self.location.origin)
      if (open) {
        // Received by NotificationClickHandler.tsx, which calls the router.
        open.postMessage({ type: 'notification-click', url: path })
        try {
          await open.focus()
        } catch {
          // focus() can be refused; the message above is already on its way
        }
        return
      }
      await clients.openWindow(target.href)
    }),
  )
})
